sys_script_include.script:
var conditionalControlsUtilsBase = Class.create();
conditionalControlsUtilsBase.prototype = {
    initialize: function() {
    },

GetConditionalCntrlObjs: function (entity, controlReferenece, newManagedState, systemType) {

	//Add new controls if managed
		var managedControls = new GlideRecord('x_631631_sc_grc_co_control_decisions');
		managedControls.addQuery('control_reference', controlReferenece);
		managedControls.addQuery('new_manage_state', 'Managed');
		managedControls.addQuery('system_type', 'CONTAINS', systemType);
		managedControls.query();
		while(managedControls.next()) {
			if(newManagedState == 'Managed' && this.CtrlObjRefExists(entity, managedControls.control_objective)=='0') {
				// gs.addInfoMessage('CO to Add: ' + managedControls.control_objective);
				var contentProfileRelationship = new GlideRecord('sn_grc_m2m_content_profile');
				if (contentProfileRelationship.canCreate()) {
					contentProfileRelationship.setValue('sn_grc_content', managedControls.control_objective);
					contentProfileRelationship.setValue('sn_grc_profile', entity);
					var addResult = contentProfileRelationship.insert();
					// gs.addInfoMessage('add result: ' + managedControls.control_objective);
					// var addRec = new GlideRecord('sn_grc_m2m_content_profile');
					// addRec.get(addResult);
					// if (addRec) gs.addInfoMessage('entity: ' + addRec.entity);

				}
			}
			else if (newManagedState=='Unmanaged') {
				var sysId = this.CtrlObjRefExists(entity, managedControls.control_objective);
				// gs.addInfoMessage('to be deleted: ' + sysId);
				if (sysId!=0) {
					var grRelate = new GlideRecord('sn_grc_m2m_content_profile');
					// gs.addInfoMessage('before count: ' + grRelate.getRowCount());
					grRelate.get(sysId);
					var delResp = grRelate.deleteRecord();
					// gs.addInfoMessage('Del Resp: ' + delResp);
				}
			}
		}

		var unManagedControls = new GlideRecord('x_631631_sc_grc_co_control_decisions');
		unManagedControls.addQuery('control_reference', controlReferenece);
		unManagedControls.addQuery('new_manage_state', 'Unmanaged');
		unManagedControls.addQuery('system_type', 'CONTAINS', systemType);
		unManagedControls.query();
		while(unManagedControls.next()) {
			// gs.addInfoMessage(newManagedState + ' - ' + unManagedControls.control_objective.name);
			if(newManagedState == 'Unmanaged' && this.CtrlObjRefExists(entity, unManagedControls.control_objective)=='0') {
				// gs.addInfoMessage('here');
				contentProfileRelationship = new GlideRecord('sn_grc_m2m_content_profile');
				if (contentProfileRelationship.canCreate()) {
					contentProfileRelationship.setValue('sn_grc_content', unManagedControls.control_objective);
					contentProfileRelationship.setValue('sn_grc_profile', entity);
					contentProfileRelationship.insert();
				}
			}
			else if (newManagedState=='Managed') {
				sysId = this.CtrlObjRefExists(entity, unManagedControls.control_objective);
				if (sysId!=0) {
					grRelate = new GlideRecord('sn_grc_m2m_content_profile');
					grRelate.get(sysId);
					grRelate.deleteRecord();
				}
			}
		}

},

CtrlObjRefExists: function (entity, ctrlObj) {
	var gr = new GlideRecord('sn_grc_m2m_content_profile');
	gr.addQuery('sn_grc_content', ctrlObj);
	gr.addQuery('sn_grc_profile', entity);
	gr.query();
	if(gr.hasNext()) {
		gr.next();
		return gr.sys_id;
	}
	return '0';

},

    type: 'conditionalControlsUtilsBase'
};
